// P1 parallel lanes (owner, 2026-10-18 21:39; v0.63.1): which files each lane owns and which only the merge step writes.
// Plan and flow: docs/ai/lanes/README.md. Lanes are opt-in: on `main` (single-lane sessions) nothing here applies.
//   node tools/lanes.mjs --check-staged     pre-commit hook: on a lane/<lane> branch refuse staged changes to shared files,
//                                           to the other lane's files, and to the VERSION line (no-op on other branches)
//   node tools/lanes.mjs --unstage-shared   unstage + restore the shared files (generated by the build) on a lane branch
//   node tools/lanes.mjs --owner <path>     prints ui, card, shared or free
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

// prefix entries end with "/", the rest are exact paths
export const LANES = {
  ui: ['apps/web/src/', 'src/styles.css', 'docs/DESIGN.md', 'docs/design/', 'docs/ai/lanes/ui.md'],
  card: ['packages/engine/src/', 'data/', 'tests/scenarios/', 'tools/compile_effects.py', 'tools/compile_v2.py',
    'tools/promote_compiled.mjs', 'tools/import_fandom.py', 'tools/tag_effects.py', 'docs/ai/lanes/card.md'],
};
// written only by the merge + release step on main (lanes put the change they need into docs/ai/lanes/<lane>.md)
export const SHARED = ['package.json', 'CHANGELOG.md', 'README.md', 'CLAUDE.md', 'index.html', 'docs/progress.html',
  'docs/roadmap.html', 'docs/roadmap-data.json', 'docs/ai/roadmap-open.md', 'docs/ai/code-map.md',
  'docs/reports/unlock-report.md', 'docs/reports/mechanic-inventory.md'];
// tests/unit/ and tests/suites/ hold UI and card tests side by side: free for both lanes (new files rarely clash)

const hit = (list, f) => list.some((p) => (p.endsWith('/') ? f.startsWith(p) : f === p));
export function owner(f) {
  if (hit(SHARED, f)) return 'shared';
  for (const [l, list] of Object.entries(LANES)) if (hit(list, f)) return l;
  return 'free';
}
// pure check used by the hook and the unit test: files = staged paths, versionChanged = the VERSION line differs from main
export function problems(lane, files, versionChanged = false) {
  const out = [];
  for (const f of files) {
    const o = owner(f);
    if (o === 'shared') out.push(`${f}: shared file, only the merge step writes it (note the change in docs/ai/lanes/${lane}.md)`);
    else if (o !== 'free' && o !== lane) out.push(`${f}: belongs to the ${o} lane`);
  }
  if (versionChanged) out.push('packages/engine/src/01-cards.js: the VERSION line is bumped only by the merge step');
  return out;
}

const git = (...a) => execFileSync('git', a, { encoding: 'utf8' }).trim();
const laneOfBranch = () => { try { const m = git('symbolic-ref', '--short', 'HEAD').match(/^lane\/(\w+)$/); return m && LANES[m[1]] ? m[1] : ''; } catch { return ''; } };
const VLINE = /^[-+]const VERSION = /m;

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const a = process.argv.slice(2);
  if (a[0] === '--owner') { console.log(owner(a[1] || '')); process.exit(0); }
  const lane = laneOfBranch();
  if (!lane) process.exit(0);
  const staged = git('diff', '--cached', '--name-only').split('\n').filter(Boolean);
  if (a[0] === '--unstage-shared') {
    const sh = staged.filter((f) => owner(f) === 'shared');
    if (sh.length) { git('restore', '--staged', '--', ...sh); git('restore', '--', ...sh); }
    console.log(`[lanes] ${sh.length} shared file(s) unstaged and restored${sh.length ? ': ' + sh.join(', ') : ''}`);
    process.exit(0);
  }
  if (a[0] === '--check-staged') {
    // a file that equals main again (e.g. after merging main into the lane) is not a lane change
    let base = 'origin/main'; try { git('rev-parse', '--verify', '-q', base); } catch { base = ''; }
    const changed = base ? staged.filter((f) => { try { return git('diff', '--cached', '--name-only', base, '--', f) !== ''; } catch { return true; } }) : staged;
    let v = false; try { v = VLINE.test(git('diff', '--cached', ...(base ? [base] : []), '--', 'packages/engine/src/01-cards.js')); } catch {}
    const p = problems(lane, changed, v);
    if (p.length) {
      console.error(`[lanes] commit refused on lane/${lane}:\n  ` + p.join('\n  ') + '\n  generated files: node tools/lanes.mjs --unstage-shared');
      process.exit(1);
    }
    process.exit(0);
  }
  console.error('usage: node tools/lanes.mjs --check-staged | --unstage-shared | --owner <path>'); process.exit(2);
}
